function firstUniqChar(s) {
  for (let i = 0; i < s.length; i++) {
    let repeated = false;
    for (let j = 0; j < s.length; j++) {
      if (i !== j && s[i] === s[j]) {         // the same letter somewhere else
        repeated = true;
        break;
      }
    }
    if (!repeated) return i;
  }
  return -1;
}

def first_uniq_char(s):
    for i in range(len(s)):
        repeated = False
        for j in range(len(s)):
            if i != j and s[i] == s[j]:   # the same letter somewhere else
                repeated = True
                break
        if not repeated:
            return i
    return -1

