function firstUniqChar(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) count[ch.charCodeAt(0) - 97]++;   // pass 1: count every letter
  for (let i = 0; i < s.length; i++) {
    if (count[s.charCodeAt(i) - 97] === 1) return i;    // pass 2: the first letter seen once
  }
  return -1;
}

def first_uniq_char(s):
    count = [0] * 26
    for ch in s:
        count[ord(ch) - ord("a")] += 1    # pass 1: count every letter
    for i, ch in enumerate(s):
        if count[ord(ch) - ord("a")] == 1:
            return i                      # pass 2: the first letter seen once
    return -1

int firstUniqChar(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) count[s.charAt(i) - 'a']++;   // pass 1: count every letter
    for (int i = 0; i < s.length(); i++) {
        if (count[s.charAt(i) - 'a'] == 1) return i;                  // pass 2: the first letter seen once
    }
    return -1;
}

